#include "kinematic_estimator.h"
void kinematic_estimator_init(kinematic_estimator_t*e,float a){*e=(kinematic_estimator_t){.alpha=motion_clampf(a,.01f,1)};}motion_state2_t kinematic_estimator_update(kinematic_estimator_t*e,motion_vec2_t p,uint64_t t){if(!e->initialized||t<=e->state.timestamp_us){e->state.position=p;e->state.timestamp_us=t;e->initialized=true;return e->state;}float dt=(t-e->state.timestamp_us)*1e-6f;if(dt<1e-5f)dt=1e-5f;motion_vec2_t v={(p.x-e->state.position.x)/dt,(p.y-e->state.position.y)/dt},a={(v.x-e->state.velocity.x)/dt,(v.y-e->state.velocity.y)/dt},j={(a.x-e->state.acceleration.x)/dt,(a.y-e->state.acceleration.y)/dt};float q=e->alpha;e->state.velocity.x+=(v.x-e->state.velocity.x)*q;e->state.velocity.y+=(v.y-e->state.velocity.y)*q;e->state.acceleration.x+=(a.x-e->state.acceleration.x)*q;e->state.acceleration.y+=(a.y-e->state.acceleration.y)*q;e->state.jerk.x+=(j.x-e->state.jerk.x)*q;e->state.jerk.y+=(j.y-e->state.jerk.y)*q;e->state.position=p;e->state.timestamp_us=t;return e->state;}
